# Generates climb batch 14's MANIFEST block (CLIMB-BATCH-14.md, rungs S, A, L and P) for the redesigned batch
# workflow (explorations/coordinator/climb-batch-workflow.js; explorations/coordinator/process-engineering/
# batch-redesign.md) from the record and the briefings of lists14.py, into $OUT14/manifest14.js ($FORTRESS_HOME/tmp
# by default, which is ignored); check14.js checks it and splices it. On batch 13's pattern (plan-13/manifest/
# gen13.py), with the redesign's entry form: each rung's section of the record's section 3 goes into the block word
# for word as the rung's section, which every role on the rung reads (the worker, the skeptic, a judge and a repair
# round), its code-span backticks dropped and any ellipsis character written as three full stops, since the
# script carries ASCII only; the briefing's reasons go beside the keys, and the script renders them at the end of the
# worker's brief; the manifest fields (slug, worktree, expected minutes, the stage as the test, the step a rung brings
# into the gate, the checker count a rung declares, the blurb and the points to report) come from the record's section 5, "The manifest, rung by rung",
# and the intro every agent reads from its "What every agent of the run reads first". No value is set at launch: the
# gather numbers the batch's new rows through ledger.py, so the block has no LEDGER_FROM.
#   python3 gen14.py [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-14.md
import json, re, sys, os
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from lists14 import LISTS, REASONS, IDS

ROOT = os.environ.get('FORTRESS_HOME', os.path.abspath(os.path.join(HERE, '../../../..')))
args = [a for a in sys.argv[1:] if not a.startswith('--')]
REC = args[0] if args else os.path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-14.md')
OUT = os.path.join(os.environ.get('OUT14', os.path.join(ROOT, 'tmp')), 'manifest14.js')
os.makedirs(os.path.dirname(OUT), exist_ok=True)
rec = open(REC, encoding='utf-8').read()


def ascii_text(t):
    t = t.replace('`', '').replace('…', '...')
    bad = [c for c in t if ord(c) > 127]
    assert not bad, ('non-ASCII left', bad, t[:120])
    return t


def between(text, start, end):
    i = text.index(start)
    j = text.index(end, i + len(start))
    return text[i + len(start):j]


# Section 3: one block per rung, from its heading to the next ### heading.
s3 = between(rec, '\n## 3. The rungs\n', '\n## 4. ')
heads = list(re.finditer(r'^### ([A-Z])\. (.*)$', s3, flags=re.M))
assert [h.group(1) for h in heads] == list(IDS), [h.group(1) for h in heads]
sections, titles = {}, {}
for i, h in enumerate(heads):
    rid = h.group(1)
    end = heads[i + 1].start() if i + 1 < len(heads) else s3.index('\n### The rule the rungs keep')
    body = s3[h.end():end].strip('\n')
    assert body.startswith('**The answers this rung follows.**'), rid
    sections[rid] = ascii_text(body)
    titles[rid] = ascii_text(h.group(2))

# Section 5: the manifest fields, rung by rung, and the intro.
s5 = rec[rec.index('\n## 5. How it is run\n'):]
mrung = between(s5, '\n### The manifest, rung by rung\n', '\n### What every agent of the run reads first\n')
blocks = list(re.finditer(r'^#### ([A-Z])$', mrung, flags=re.M))
assert [b.group(1) for b in blocks] == list(IDS), [b.group(1) for b in blocks]
FIELDS = {}
for i, b in enumerate(blocks):
    rid = b.group(1)
    text = mrung[b.end():blocks[i + 1].start() if i + 1 < len(blocks) else len(mrung)]
    f, points, in_points = {}, [], False
    for line in text.split('\n'):
        m = re.match(r'^- \*\*([a-z ]+):\*\*\s*(.*)$', line)
        if m:
            key, val = m.group(1), m.group(2).strip()
            in_points = (key == 'points to report')
            if not in_points:
                f[key] = ascii_text(val)
            continue
        m = re.match(r'^  - (.*)$', line)
        if m and in_points:
            points.append(ascii_text(m.group(1).strip()))
    f['points'] = points
    for k in ('slug', 'worktree', 'expected minutes', 'its test is the stage', 'writes state', 'joins the gate', 'checker count', 'blurb'):
        assert k in f, (rid, k)
    assert points, (rid, 'no points to report')
    FIELDS[rid] = f
intro = between(s5, '\n### What every agent of the run reads first\n', '\n### Before the launch\n').strip()
INTRO = ascii_text(intro)

def yes(v):
    assert v in ('yes', 'no'), v
    return v == 'yes'

def js(x):
    return json.dumps(x, ensure_ascii=True)

def js_list(keys, indent='      '):
    out, cur = [], ''
    for k in keys:
        piece = js(k)
        if cur and len(cur) + len(piece) + 2 > 150:
            out.append(indent + cur.rstrip())
            cur = ''
        cur += piece + ', '
    if cur:
        out.append(indent + cur.rstrip().rstrip(','))
    return '\n'.join(out)

L = []
A = L.append
A('// ===========================================================================')
A('// MANIFEST - the coordinator replaces everything between this line and the')
A('// "END MANIFEST" line, and changes nothing else in this file.')
A('//')
A('// Generated by explorations/compile-ladder/plan-14/manifest/gen14.py from')
A('// CLIMB-BATCH-14.md (section 3, each rung\'s section word for word; section 5, the')
A('// manifest fields and the intro) and the briefings of lists14.py; check14.js checks it.')
A('// Per rung: id, slug, path, branch, expectedMinutes (the scatter\'s start order only),')
A('// writesState, testIsStage, gateJoins (a gate step the rung brings), blurb (one line')
A('// for the batch table), section (the rung\'s section of the record, read by every role')
A('// on the rung), pointsToReport, briefing and reasons (the facts-extract.sh keys the')
A('// worker reads first, each with its reason), checks (the sub-list the skeptic, a judge')
A('// and a repair round read), expectedMoves (ladder moves declared, none here), and the')
A('// optional landsOnlyWith, expectedCheckerCount and expectedCheckerCrash (rung L declares')
A('// the checker count 1, its one error moving by reading from body(i) to row 680\'s crash;')
A('// no rung declares landsOnlyWith or a crash).')
A('// No value is set at launch. The base and the base build are args.base and')
A('// args.baseBuild. At most two agents run at once on this box, FIFO (FACTS.md, "The')
A('// Workflow harness runs two agents at once on this box"); the scatter starts the')
A('// longest expected worker first.')
A('// ===========================================================================')
A('')
A("const BATCH = '14'")
A("const BATCH_RECORD = 'explorations/coordinator/CLIMB-BATCH-14.md'")
A("const BRIEFING_LISTS = 'explorations/compile-ladder/plan-14/manifest/lists14.py'")
A('')
for rid in IDS:
    A('const %s_SECTION = [' % rid)
    for l in sections[rid].split('\n'):
        A(js(l) + ',')
    A("].join('\\n')")
    A('')
for rid in IDS:
    f = FIELDS[rid]
    b, c = LISTS[rid]
    slug = f['slug']
    assert re.fullmatch(r'[a-z0-9-]+', slug), slug
    path = f['worktree']
    assert re.fullmatch(r'/home/user/fortress-[a-z0-9-]+', path), path
    joins = [] if f['joins the gate'] == 'none' else [x.strip() for x in f['joins the gate'].split(',')]
    A("const %s_ENTRY = { id: '%s', slug: '%s', path: '%s', branch: 'wip/%s', expectedMinutes: %d," % (rid, rid, slug, path, slug, int(f['expected minutes'])))
    cc = f['checker count']
    assert cc == 'none' or re.fullmatch(r'[0-9]+', cc), (rid, cc)
    A('    writesState: %s, testIsStage: %s, gateJoins: %s, expectedMoves: [],%s' % ('true' if yes(f['writes state']) else 'false', 'true' if yes(f['its test is the stage']) else 'false', js(joins), '' if cc == 'none' else ' expectedCheckerCount: %d,' % int(cc)))
    A('    title: ' + js(titles[rid]) + ',')
    A('    blurb: ' + js(f['blurb']) + ',')
    A('    section: %s_SECTION,' % rid)
    A('    pointsToReport: [')
    for p in f['points']:
        A('      ' + js(p) + ',')
    A('    ],')
    A('    briefing: [')
    A(js_list(b) + '],')
    A('    reasons: [')
    for k, r in REASONS[rid]:
        A('      ' + js(ascii_text(r)) + ',')
    A('    ],')
    A('    checks: [')
    A(js_list(c) + '] }')
    A('')
A('const RUNGS = [' + ', '.join('%s_ENTRY' % r for r in IDS) + ']')
A('const BATCH_INTRO = ' + js(INTRO))
BLOCK = '\n'.join(L) + '\n'
for line in L:
    assert all(ord(c) < 128 for c in line) and '`' not in line, line[:120]
open(OUT, 'w').write(BLOCK)
print('wrote', OUT, len(L), 'lines')
for rid in IDS:
    print(rid, FIELDS[rid]['slug'], FIELDS[rid]['worktree'], 'section', len(sections[rid]), 'chars;', len(FIELDS[rid]['points']), 'points;', len(LISTS[rid][0]), 'briefing keys,', len(LISTS[rid][1]), 'checks')
// Checks climb batch 14's MANIFEST block (gen14.py's output, $OUT14/manifest14.js) spliced into a scratch copy of
// the workflow script, and with --write splices it into the tracked script. On batch 13's pattern
// (plan-13/manifest/check13.js), for the redesigned script (explorations/coordinator/process-engineering/
// batch-redesign.md): node --check on the original and the spliced copy; both parsed as the body of an async
// function, as the Workflow harness parses them, their export made const (the coordinator skill's
// references/delegating.md: a script is checked by parsing it as an async function body); every line outside the block byte-identical; the block
// evaluated with the script's own load checks and scatter order; the rungs S, A, L, P, their fields, no rung
// bringing a gate step (testSpecData runs from climb batch 13b's landed summary), rung L alone declaring a
// checker count, 1, and no rung a crash, landsOnlyWith or a ladder move; each
// section equal to the rung's section 3 of the record (backticks dropped, the
// ellipsis character as three full stops); briefing, reasons and checks equal to lists14.py's, one reason per key,
// checks a sub-list of the briefing; no backtick or non-ASCII character in any string the agents read; no text
// asking a skeptic to see a failure again or a stage re-run without a code change (the coordinator skill's
// references/batch.md, "The workflow"); no LEDGER_FROM (the gather numbers rows through ledger.py); the record holding
// no copy of the block. Its last lines say whether the tracked script's block equals the generated one, and count
// the problems.
//   node check14.js [--write] [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-14.md
const fs = require('fs')
const cp = require('child_process')
const path = require('path')
const ROOT = process.env.FORTRESS_HOME || path.resolve(__dirname, '../../../..')
const HERE = process.env.OUT14 || path.join(ROOT, 'tmp')
const SRC = path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.js')
const argv = process.argv.slice(2)
const WRITE = argv.includes('--write')
const REC = argv.filter(a => !a.startsWith('--'))[0] || path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-14.md')
const block = fs.readFileSync(path.join(HERE, 'manifest14.js'), 'utf8')
const orig = fs.readFileSync(SRC, 'utf8')
let bad = 0
const say = (ok, text) => { if (!ok) bad++; console.log((ok ? 'ok   ' : 'BAD  ') + text) }

function bounds(text) {
  const ls = text.split('\n')
  const m = ls.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces'))
  if (m < 1 || !/^\/\/ =+$/.test(ls[m - 1])) throw new Error('no rule above the MANIFEST line')
  const e = ls.findIndex(l => l.startsWith('// =========================== END MANIFEST'))
  if (e < m) throw new Error('no END MANIFEST line after the MANIFEST line')
  return { ls, start: m - 1, end: e }
}
const o = bounds(orig)
const pre = o.ls.slice(0, o.start).join('\n'), post = o.ls.slice(o.end).join('\n')
const current = o.ls.slice(o.start, o.end).join('\n') + '\n'
const spliced = pre + '\n' + block + post
const out = path.join(HERE, 'wf-spliced-14.js')
fs.writeFileSync(out, spliced)
console.log('the script\'s MANIFEST block is lines ' + (o.start + 1) + ' to ' + o.end + ' of ' + o.ls.length + '; the generated block has ' + block.split('\n').length + ' lines')
say(spliced.startsWith(pre + '\n') && spliced.endsWith(post) && block.endsWith('\n') && !block.split('\n').some(l => l.startsWith('// =========================== END MANIFEST')), 'every line outside the block is byte-identical, and the block ends before END MANIFEST')

for (const f of [SRC, out]) {
  const r = cp.spawnSync('node', ['--check', f], { encoding: 'utf8' })
  say(r.status === 0, 'node --check ' + path.basename(f) + ': exit ' + r.status + (r.status ? ' ' + r.stderr.trim().slice(0, 300) : ''))
}
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
for (const [name, text] of [['original', orig], ['spliced', spliced]]) {
  try { new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', 'phase', 'budget', 'workflow', text.replace(/^export const meta/m, 'const meta')); say(true, 'the harness\'s parse: ' + name + ' accepted as an async function body, its export made const') }
  catch (e) { say(false, 'the harness\'s parse: ' + name + ' refused: ' + e.message) }
}

// The block, evaluated with the script's load checks (const LOOKUP_TOOL ... const keysOf) and its scatter line.
const s = bounds(spliced)
const manifest = s.ls.slice(s.start, s.end).join('\n')
const vStart = s.ls.findIndex(l => l.startsWith('const LOOKUP_TOOL = '))
const vEnd = s.ls.findIndex(l => l.startsWith('const keysOf = '))
const validation = s.ls.slice(vStart, vEnd + 1).join('\n')
const scatter = s.ls.find(l => l.startsWith('const SCATTER = '))
let r = null
try {
  r = new Function("const TOOLS = 'explorations/coordinator/tools'\n" + manifest + '\n' + scatter + '\n' + validation +
    '\nreturn { BATCH, BATCH_RECORD, BRIEFING_LISTS, RUNGS, SCATTER, BATCH_INTRO, ledgerFrom: typeof LEDGER_FROM }')()
  say(true, 'the block passes the script\'s own load checks')
} catch (e) { say(false, 'the block fails the script\'s load checks: ' + e.message) }

if (r) {
  const ids = r.RUNGS.map(x => x.id).join(', ')
  const order = r.RUNGS.slice().sort((a, b) => b.expectedMinutes - a.expectedMinutes).map(x => x.id).join('')
  console.log('batch ' + r.BATCH + ', rungs ' + ids + ', scatter ' + r.SCATTER.map(x => x.id).join('') + ', intro ' + r.BATCH_INTRO.length + ' characters')
  say(r.BATCH === '14' && r.BATCH_RECORD === 'explorations/coordinator/CLIMB-BATCH-14.md' && r.BRIEFING_LISTS === 'explorations/compile-ladder/plan-14/manifest/lists14.py' && ids === 'S, A, L, P' && r.SCATTER.map(x => x.id).join('') === order, 'batch 14, its record and lists, the rungs S, A, L, P and the scatter by expected minutes')
  say(r.ledgerFrom === 'undefined', 'no LEDGER_FROM: the gather numbers the new rows through ledger.py')
  say(JSON.stringify(r.RUNGS.map(x => x.gateJoins)) === JSON.stringify([[], [], [], []]), 'no rung brings a gate step: testSpecData runs from the last landed summary')
  say(r.RUNGS.every(x => !x.landsOnlyWith && x.expectedCheckerCrash === undefined && Array.isArray(x.expectedMoves) && !x.expectedMoves.length), 'no rung declares landsOnlyWith, a crash or a ladder move')
  say(JSON.stringify(r.RUNGS.map(x => x.expectedCheckerCount === undefined ? null : x.expectedCheckerCount)) === JSON.stringify([null, null, 1, null]), 'rung L alone declares a checker count, 1 (body(i) typed, its one error moving by reading to row 680\'s crash)')

  // The record's section 3, rung by rung, as gen14.py reads it.
  const rec = fs.readFileSync(REC, 'utf8')
  const s3 = rec.slice(rec.indexOf('\n## 3. The rungs\n'), rec.indexOf('\n## 4. '))
  const asAscii = (t) => t.replace(/`/g, '').replace(/…/g, '...')
  function section(id) {
    const m = new RegExp('^### ' + id + '\\. .*$', 'm').exec(s3)
    if (!m) return null
    const rest = s3.slice(m.index + m[0].length)
    const nx = rest.search(/^### /m)
    return asAscii((nx < 0 ? rest : rest.slice(0, nx)).replace(/^\n+|\n+$/g, ''))
  }
  // lists14.py's briefings, reasons and checks.
  const py = cp.spawnSync('python3', ['-B', '-c', 'import json, sys; sys.path.insert(0, sys.argv[1]); from lists14 import LISTS, REASONS, IDS; ' +
    'print(json.dumps({r: {"briefing": LISTS[r][0], "checks": LISTS[r][1], "reasons": [x for _, x in REASONS[r]]} for r in IDS}))', __dirname], { encoding: 'utf8' })
  const lists = py.status === 0 ? JSON.parse(py.stdout) : null
  say(!!lists, 'lists14.py read' + (lists ? '' : ': ' + py.stderr.trim().slice(0, 300)))
  const rerun = /sees? it fail again|re-?run by the skeptic|skeptic re-?runs|run the stage yourself|skeptic rebuilds|re-anchor/i
  for (const x of r.RUNGS) {
    const want = section(x.id)
    say(want !== null && x.section === want, x.id + ': its section is the record\'s section 3 for ' + x.id + ' word for word (' + x.section.length + ' characters)')
    const l = lists && lists[x.id]
    say(!!l && JSON.stringify(x.briefing) === JSON.stringify(l.briefing) && JSON.stringify(x.checks) === JSON.stringify(l.checks) &&
      JSON.stringify(x.reasons) === JSON.stringify(l.reasons.map(asAscii)), x.id + ': briefing ' + x.briefing.length + ' keys, reasons ' + x.reasons.length + ', checks ' + x.checks.length + ', as lists14.py has them')
    say(x.checks.every(k => x.briefing.includes(k)), x.id + ': checks a sub-list of the briefing')
    say(x.branch === 'wip/' + x.slug && /^\/home\/user\/fortress-[a-z0-9-]+$/.test(x.path) && x.expectedMinutes > 0, x.id + ': ' + x.path + ' on ' + x.branch + ', ' + x.expectedMinutes + ' minutes')
    say(Array.isArray(x.pointsToReport) && x.pointsToReport.length > 0 && x.pointsToReport.every(p => typeof p === 'string' && p.trim()), x.id + ': ' + x.pointsToReport.length + ' points to report')
    const texts = [x.title, x.blurb, x.section].concat(x.pointsToReport, x.reasons, x.briefing)
    say(!texts.some(t => /[^\x00-\x7f`]/.test(t) || /`/.test(t)), x.id + ': no backtick or non-ASCII character')
    say(!texts.some(t => rerun.test(t)), x.id + ': nothing asks a skeptic to see a failure again, rebuild, re-run or re-anchor')
  }
  say(!/[^\x00-\x7f]|`/.test(r.BATCH_INTRO) && !rerun.test(r.BATCH_INTRO), 'the intro: ASCII, no backtick, no re-run')
  const paths = r.RUNGS.map(x => x.path), slugs = r.RUNGS.map(x => x.slug)
  say(new Set(paths).size === paths.length && new Set(slugs).size === slugs.length, 'every rung has its own worktree and branch')
  say(!rec.includes('const RUNGS') && !rec.includes('_ENTRY = {') && rec.includes('gen14.py') && rec.includes('check14.js'), 'the record names gen14.py and check14.js and holds no copy of the block')
}

const same = current === block
console.log((same ? 'the tracked script\'s block equals the generated one' : 'the tracked script\'s block differs from the generated one') + (WRITE ? '' : '; --write splices it'))
if (WRITE) {
  if (bad) console.log('not written: ' + bad + ' problem(s)')
  else if (same) console.log('nothing to write')
  else { fs.writeFileSync(SRC, spliced); console.log('wrote the block into ' + path.relative(ROOT, SRC)) }
}
console.log('problems: ' + bad)

